const experienceMap = {
  "Less than 1 year": "1",
  "1 to 2 years": "2",
  "3 to 5 years": "3",
  "6 to 10 years": "4",
  "More than 10 years": "5"
};

const seniorityMap = {
  "Intern": "100",
  "Junior": "110",
  "Senior": "120",
  "Strategic": "130",
  "Entry Level Manager": "200",
  "Experienced Manager": "210",
  "Director": "220"
};

return items.map(item => {
  const d = item.json;

  // 1. Helper to clean arrays (removes nulls, undefined, and empty strings)
  const toCleanArray = (val) => {
    if (!val) return [];
    let arr = Array.isArray(val) ? val : val.split(',').map(s => s.trim());
    return arr.filter(s => s !== null && s !== undefined && s !== "");
  };

  // 2. Process Seniority (Handles stringified arrays, normal arrays, or single strings)
  let sInput = d.seniority_level;
  if (typeof sInput === 'string' && sInput.startsWith('[')) {
    try { 
      sInput = JSON.parse(sInput); 
    } catch (e) { 
      sInput = toCleanArray(sInput.replace(/[\[\]"]/g, '')); 
    }
  } else {
    sInput = toCleanArray(sInput);
  }

  // Map labels to IDs and remove any that didn't map correctly or are null
  const seniorityIds = (Array.isArray(sInput) ? sInput : [sInput])
    .map(s => seniorityMap[s] || s)
    .filter(s => s !== null && s !== undefined && s !== "");

  // 3. Process Experience
  const expInput = toCleanArray(d.years_of_experience);
  const experienceIds = expInput
    .map(e => experienceMap[e] || e)
    .filter(e => e !== null && e !== undefined && e !== "");

  // 4. Build the final output with strict null-safety
  const payload = {
    autoQuerySegmentation: false,
    locations: d.location ? [d.location] : [],
    maxItems: parseInt(d.desired_number) || 20,
    pastCompanies: toCleanArray(d.past_companies),
    profileScraperMode: "Full",
    recentlyChangedJobs: false,
    schools: toCleanArray(d.education),
    searchQuery: d.search_query || "",
    profileLanguage: d.profile_language || "English"
  };

  // Only add these keys if they have actual values to avoid Apify "must be string" errors
  if (seniorityIds.length > 0) payload.seniorityLevelIds = seniorityIds;
  if (experienceIds.length > 0) payload.yearsOfExperienceIds = experienceIds;

  return { json: payload };
});

